function Empty({title,children,action}:{title:string;children:React.ReactNode;action?:React.ReactNode}){return <section className="single-pocket"><div className="empty-ring" aria-hidden="true"/><h2>{title}</h2><p>{children}</p><div className="actions">{action}</div></section>}
function App(){
 const m=useMockup(),profile=useMotionProfile();
 const [lang,setLang]=React.useState(model.lang),[actor,setActor]=React.useState(m.view==='ajeno'&&model.actor==='usuario'?'staff':model.actor),[query,setQuery]=React.useState(''),[owner,setOwner]=React.useState('all'),[scope,setScope]=React.useState(model.scope),[limit,setLimit]=React.useState(3),[pageFailed,setPageFailed]=React.useState(m.state==='paginaerror'),[zip,setZip]=React.useState(0),[name,setName]=React.useState(m.view==='importar'?(model.imported?model.name:'Montaje del navegador'):model.copy?model.name+' · copia':model.named?model.name:''),[invalid,setInvalid]=React.useState(false),[,refresh]=React.useState(0);
 const root=React.useRef<HTMLDivElement>(null),focusFrom=React.useRef<HTMLElement|null>(null);
 const en=lang==='en',t=(es:string,eng:string)=>en?eng:es;
 const staff=actor!=='usuario',canEdit=actor!=='lectura',forbidden=m.state==='sinpermiso',ended=m.state==='sesion',busy=m.state==='cargando',empty=m.state==='vacio',offline=m.state==='sinconexion',conflict=m.state==='conflicto',saving=m.state==='guardando',pending=m.state==='pendiente',saved=m.state==='guardado',error=m.state==='error',validation=m.state==='validacion';
 const open=(scene:string)=>{focusFrom.current=document.activeElement as HTMLElement;m.set('scene',scene)};
 const close=()=>{m.set('scene','');requestAnimationFrame(()=>focusFrom.current?.isConnected&&focusFrom.current.focus())};
 const go=(view:string)=>{if((model.dirty||pending||saving)&&m.view==='taller'){open('salir');return}m.set('view',view);requestAnimationFrame(()=>document.querySelector<HTMLElement>('.display')?.focus())};
 const newProject=()=>{model.name=t('Sin título','Untitled');model.revision=0;model.named=false;model.dirty=false;model.added=0;model.notice='';model.auto=false;go('taller')};
 React.useEffect(()=>{const vis=()=>document.documentElement.toggleAttribute('data-hidden',document.hidden);document.addEventListener('visibilitychange',vis);vis();const observer=new IntersectionObserver(items=>items.forEach(item=>item.target.classList.toggle('offscreen',!item.isIntersecting)),{rootMargin:'40px'});root.current?.querySelectorAll('.pocket,.scene-shell').forEach(el=>observer.observe(el));return()=>{document.removeEventListener('visibilitychange',vis);observer.disconnect()}},[]);
 React.useEffect(()=>{if(!model.auto||m.view!=='taller')return;if(m.state==='pendiente'){const id=setTimeout(()=>m.set('state','guardando'),1400);return()=>clearTimeout(id)}if(m.state==='guardando'){const id=setTimeout(()=>{model.dirty=false;model.auto=false;model.revision++;const p=projects.find(p=>p.name===model.name&&p.owner==='Ana Torres');if(p)p.revision=model.revision;m.set('state','guardado')},900);return()=>clearTimeout(id)}},[m.state,m.view]);
 const save=()=>{if(!model.named){model.copy=false;setName('');open('nombre')}else{model.auto=true;m.set('state','guardando')}};
 const edit=()=>{model.added++;model.dirty=true;model.notice='';if(!offline&&!conflict){if(model.named){model.auto=true;m.set('state','pendiente')}else refresh(x=>x+1)}else refresh(x=>x+1)};
 const copy=()=>{if(m.view==='ajeno')model.style=model.readStyle;model.copy=true;setName((m.view==='ajeno'?model.readName:model.name)+' · '+t('copia','copy'));open('nombre')};
 const commitName=()=>{if(!name.trim()){setInvalid(true);return}const creates=model.copy||!model.named;model.name=name.trim();model.named=true;model.dirty=false;model.revision=creates?1:Math.max(1,model.revision);if(creates)projects.unshift({name:model.name,owner:'Ana Torres',date:'27 oct · 9:45',revision:1,style:model.style});model.notice=t('Simulación: proyecto guardado en tu cuenta.','Simulation: project saved to your account.');model.auto=false;model.copy=false;close();m.set('view','taller');m.set('state','guardado')};
 const filtered=projects.filter(p=>(staff&&scope==='all'||p.owner==='Ana Torres')&&(owner==='all'||p.owner===owner)&&p.name.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 const title=m.view==='lista'?t('Proyectos','Projects'):m.view==='importar'?t('Del navegador\na tu cuenta','From this browser\nto your account'):m.view==='ajeno'?model.readName:model.name;
 const status=busy?t('Abriendo proyecto…','Opening project…'):conflict?t('Hay otra versión guardada','Another version was saved'):offline?t('Sin conexión · cambios locales','Offline · local changes'):saving?t('Guardando…','Saving…'):pending?t('Cambios pendientes','Changes pending'):error?t('No se pudo guardar','Could not save'):!model.named?t('Todavía sin guardar','Not saved yet'):saved?t('Guardado en tu cuenta','Saved to your account'):t('Guardado · revisión ','Saved · revision ')+model.revision;
 const retry=()=>{model.auto=false;m.set('state','normal')};
 function Notice(){if(forbidden||ended)return null;if(m.view==='ajeno'){if(error)return <section className="notice error" role="alert"><CloudOff/><div><strong>{t('No pudimos abrir el proyecto','Could not open the project')}</strong><p>{t('El original no se ha modificado. Reintenta la consulta.','The original has not changed. Retry viewing it.')}</p><div className="actions"><B onClick={retry}>{t('Reintentar','Retry')}</B></div></div></section>;if(offline)return <section className="notice" role="status"><CloudOff/><div><strong>{t('Sin conexión · consulta desactualizada','Offline · preview may be stale')}</strong><p>{t('Esta vista conservada puede no ser la versión más reciente. No se puede crear una copia sin conexión.','This retained view may not be the latest version. A copy cannot be created offline.')}</p><div className="actions"><B onClick={retry}>{t('Reintentar conexión','Retry connection')}</B></div></div></section>;return null}if(conflict&&m.view==='taller')return <section className="notice error" role="alert"><CloudOff/><div><strong>{t('El autoguardado está pausado','Autosave is paused')}</strong><p>{t('Otra pestaña guardó una versión nueva. Tu montaje local sigue aquí. Elige cómo continuar; no se sobrescribirá ninguna versión automáticamente.','Another tab saved a newer version. Your local project is still here. Choose how to continue; no version will be overwritten automatically.')}</p><div className="conflict-compare"><div><h3>{t('Tu trabajo local','Your local work')}</h3><p>{t('Cambios pendientes · desde revisión ','Pending changes · based on revision ')}{model.revision}</p></div><div><h3>{t('En tu cuenta','In your account')}</h3><p>{t('Revisión ','Revision ')}{model.revision+1}{t(' · guardada a las 9:44',' · saved at 9:44')}</p></div></div><div className="actions"><B variant="default" onClick={copy} disabled={!canEdit}>{t('Guardar mi trabajo como copia','Save my work as a copy')}</B><B onClick={()=>open('servidor')}>{t('Cargar versión guardada','Load saved version')}</B></div></div></section>;
 if(offline)return <section className="notice" role="status"><CloudOff/><div><strong>{t('Tu cuenta no ha recibido estos cambios','These changes have not reached your account')}</strong><p>{t('Puedes seguir trabajando aquí. Conservamos un borrador para esta cuenta en este navegador; reintenta cuando vuelva la conexión.','You can keep working here. A draft is kept for this account in this browser; retry when the connection returns.')}</p><div className="actions"><B onClick={retry}><RotateCcw/>{t('Reintentar conexión','Retry connection')}</B></div></div></section>;
 if(error)return <section className="notice error" role="alert"><CloudOff/><div><strong>{m.view==='lista'?t('No pudimos cargar tus proyectos','Could not load your projects'):m.view==='importar'?t('No recibimos confirmación de importación','Import confirmation was not received'):t('No pudimos guardar los cambios','Could not save your changes')}</strong><p>{m.view==='importar'?t('El original del navegador sigue intacto. Reintentar recuperará el mismo proyecto si ya se creó.','The browser original is intact. Retrying returns the same project if it was already created.'):t('Tu trabajo se conserva en este navegador. Reintenta para continuar.','Your work is kept in this browser. Retry to continue.')}</p><div className="actions"><B onClick={retry}>{t('Reintentar','Retry')}</B></div></div></section>;
 if(saved&&m.view!=='lista')return <section className="notice success" role="status"><Check/><div><strong>{m.view==='importar'?t('Escena importada a tu cuenta','Scene imported to your account'):t('Guardado en tu cuenta','Saved to your account')}</strong><p>{m.view==='importar'?t('El original del navegador se conserva. Reintentar esta importación no crea otro proyecto.','The browser original is kept. Retrying this import does not create another project.'):t('Nombre y escena completa disponibles en otros navegadores. La conversación y las imágenes de IA permanecen en este navegador.','Name and complete scene available in other browsers. AI conversations and generated images remain in this browser.')}</p></div></section>;
 return null}
 function List(){return <>{model.localKept&&<section className="notice" role="status"><FolderOpen/><div><strong>{t('Hay un borrador de esta cuenta en este navegador','A draft for this account is kept in this browser')}</strong><p>{t('Aún no está guardado en tu cuenta. Puedes volver a abrirlo aquí.','It is not saved to your account yet. You can reopen it here.')}</p><div className="actions"><B onClick={()=>{model.localKept=false;model.dirty=true;model.auto=false;m.set('state','pendiente');go('taller')}}>{t('Recuperar borrador local','Recover local draft')}</B></div></div></section>}<div className="collection-tools"><label className="field"><span>{t('Buscar en tus proyectos','Search all your projects')}</span><div className="searchbox"><Search/><Input className="entry" value={query} onChange={e=>{setQuery(e.target.value);setLimit(3);setPageFailed(false)}} placeholder={t('Nombre del proyecto','Project name')}/></div></label>{staff?<nav className="scope-nav" aria-label={t('Alcance de proyectos','Project scope')}><B variant="ghost" aria-pressed={scope==='mine'} onClick={()=>{model.scope='mine';setScope('mine');setOwner('all');setLimit(3)}}>{t('Mis proyectos','My projects')}</B><B variant="ghost" aria-pressed={scope==='all'} onClick={()=>{model.scope='all';setScope('all');setOwner('all');setLimit(3)}}>{t('Todos','Everyone')}</B></nav>:<p className="small">{t('Solo tus proyectos','Your projects only')}</p>}{staff&&scope==='all'&&<label className="field owner-filter"><span>{t('Propietario','Owner')}</span><select className="native" value={owner} onChange={e=>{setOwner(e.target.value);setLimit(3);setPageFailed(false)}}><option value="all">{t('Todas las personas','Everyone')}</option>{['Ana Torres','Mateo Ruiz','Sara Gómez'].map(n=><option key={n}>{n}</option>)}</select></label>}</div>{busy?<div className="pocket-wall" aria-busy="true" aria-label={t('Cargando proyectos','Loading projects')}>{[0,1,2].map(n=><div className="skeleton-pocket" key={n}><Skeleton className="skeleton-art"/><Skeleton className="skeleton-line"/><Skeleton className="skeleton-line short"/></div>)}</div>:empty||filtered.length===0?<Empty title={query?t('No hay coincidencias','No matches'):t('Un lugar para tus próximos montajes','A place for your next projects')} action={query?<B onClick={()=>{setQuery('');setOwner('all')}}>{t('Limpiar búsqueda','Clear search')}</B>:<B variant="default" onClick={newProject} disabled={!canEdit}>{t('Crear mi primer proyecto','Create my first project')}</B>}>{query?t('Prueba otro nombre. La búsqueda abarca toda la colección autorizada.','Try a different name. Search covers your entire authorized collection.'):t('Guarda un montaje con nombre y vuelve a abrirlo desde cualquier navegador.','Save a named project and reopen it from any browser.')}</Empty>:!error&&<><div className="collection-count" aria-live="polite"><span>{filtered.slice(0,limit).length} {t('proyectos cargados','projects loaded')}</span><span className="small">{t('Más recientes primero','Newest first')} · {t('Ana Torres · tu cuenta','Ana Torres · your account')}</span></div><div className="pocket-wall">{filtered.slice(0,limit).map((p,i)=><article className="pocket" key={p.name}><div className="pocket-head"><span>{p.owner==='Ana Torres'?t('Tu proyecto','Your project'):p.owner}</span><span className="rivet" aria-hidden="true"/></div><Art variant={p.style}/><h2>{p.name}</h2><p>{t('Último guardado','Last saved')} {p.date}</p><p>{t('Revisión','Revision')} {p.revision}{p.owner!=='Ana Torres'?' · '+t('Solo lectura','Read only'):''}</p><div className="actions"><B variant={i===0?'default':'outline'} onClick={()=>{model.readName=p.name;model.readOwner=p.owner;model.readRevision=p.revision;model.readStyle=p.style;model.name=p.name;model.named=true;model.revision=p.revision;model.style=p.style;model.notice='';model.dirty=false;go(p.owner!=='Ana Torres'||!canEdit?'ajeno':'taller')}}>{p.owner!=='Ana Torres'||!canEdit?t('Consultar montaje','View project'):t('Continuar montaje','Continue project')}<ArrowRight/></B></div></article>)}</div>{(limit<filtered.length||pageFailed)&&<div className="pagination-note"><p>{pageFailed?t('No pudimos cargar la siguiente página. Los proyectos cargados se conservan.','The next page could not be loaded. Loaded projects are kept.'):t('Hay más montajes en tu cuenta.','There are more projects in your account.')}</p><B onClick={()=>{setPageFailed(false);setLimit(x=>x+3)}}>{pageFailed?t('Reintentar siguiente página','Retry next page'):t('Cargar más proyectos','Load more projects')}</B></div>}</>}<div className="more"><B variant="ghost" onClick={()=>go('importar')}><FolderOpen/>{t('Revisar escena de este navegador','Review this browser’s scene')}</B></div></>}
 function Taller({foreign=false}:{foreign?:boolean}){return <>{!foreign&&!model.importLater&&!model.imported&&!busy&&<section className="notice import-offer"><FolderOpen/><div><strong>{t('Este navegador conserva un montaje anterior','This browser holds an earlier project')}</strong><p>{t('Puedes revisarlo e importarlo a tu cuenta. En un equipo compartido podría pertenecer a otra persona; todavía no se ha subido.','You can review it and import it to your account. On a shared device it may belong to someone else; it has not been uploaded.')}</p><div className="actions"><B onClick={()=>go('importar')}>{t('Revisar escena del navegador','Review browser scene')}</B><B onClick={()=>{model.importLater=true;refresh(x=>x+1)}}>{t('Ahora no','Not now')}</B></div></div></section>}{!foreign&&<div className="save-strip" role="status"><div><strong>{offline?<CloudOff/>:saved?<Check/>:<Cloud/>}{status}</strong><p>{!model.named?t('Ponle nombre para guardarlo por primera vez.','Give it a name for the first save.'):t('Después del primer guardado, los cambios se guardan automáticamente.','After the first save, changes save automatically.')}</p></div><div className="actions"><B variant="default" onClick={save} disabled={busy||saving||offline||conflict||!canEdit}>{t(model.named?'Guardar ahora':'Guardar proyecto',model.named?'Save now':'Save project')}</B></div></div>}{foreign&&<section className="notice"><LockKeyhole/><div><strong>{t('Solo lectura · el original se conserva','Read only · the original is preserved')}</strong><p>{t('Puedes consultarlo. Para modificarlo necesitas una copia en tu cuenta y acceso al Taller 3D.','You can view it. To edit, you need a copy in your account and access to the 3D Workshop.')}</p></div></section>}<div className="project-plane"><div className="scene-shell">{busy?<div aria-busy="true"><Skeleton className="skeleton-art"/><p>{t('Abriendo escena completa…','Opening complete scene…')}</p></div>:foreign&&error?<p>{t('Vista pendiente de cargar','Preview awaiting retry')}</p>:<Art variant={foreign?model.readStyle:model.style} empty={empty}/>}<div className="scene-caption"><span>{t('Vista esquemática ilustrativa','Illustrative schematic view')}</span><span>{foreign?t('Lectura del original','Original read only'):t('Taller 3D · zona de montaje','3D Workshop · project area')}</span></div>{!foreign&&<div className="actions scene-actions"><B disabled={busy||!canEdit} onClick={edit}><Plus/>{t('Simular cambio en la escena','Simulate scene edit')}</B><span className="small">{model.added} {t('cambios simulados','simulated changes')}</span></div>}</div><aside className="project-note"><h2>{foreign?t('Consulta y continúa en una copia','Explore and continue in a copy'):t('Lo que viaja contigo','What travels with you')}</h2><p>{foreign?t('El original no se puede editar desde esta vista.','The original cannot be edited from this view.'):t('El nombre y la escena completa se guardan en tu cuenta.','The name and complete scene are stored in your account.')}</p><dl><div><dt>{t('Propietario','Owner')}</dt><dd>{foreign?model.readOwner:'Ana Torres'}</dd></div><div><dt>{t('Versión guardada','Saved version')}</dt><dd>{t('Revisión','Revision')} {foreign?model.readRevision:model.revision}</dd></div><div><dt>{t('Permanece en este navegador','Stays in this browser')}</dt><dd>{t('Conversación e imágenes generadas por IA','AI conversation and generated images')}</dd></div></dl><div className="actions">{foreign&&<B variant="default" disabled={!canEdit||busy||offline} onClick={copy}>{t('Crear copia en mi cuenta','Create a copy in my account')}</B>}{foreign&&!canEdit&&<p className="small">{t('Tu rol permite consultar proyectos, pero no usar el Taller. Pide acceso al administrador para crear una copia.','Your role can view projects but cannot use the Workshop. Ask your administrator for access to create a copy.')}</p>}<B onClick={()=>go('lista')}><ArrowLeft/>{t('Volver a proyectos','Back to projects')}</B></div></aside></div>{model.notice&&<p className="small" role="status" style={{marginTop:20}}>{model.notice}</p>}</>}
 function Import(){const done=saved||model.imported;const download=()=>{const raw=JSON.stringify({version:2,nombre:'Montaje del navegador',escena:{illustrative:true}},null,2);const a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent(raw);a.download='escena-navegador-mockup.json';a.click()};return empty?<Empty title={t('No hay una escena por importar','No scene to import')} action={<B onClick={()=>go('lista')}>{t('Volver a proyectos','Back to projects')}</B>}>{t('En este navegador no encontramos una escena antigua. Tus proyectos guardados están en tu cuenta.','No legacy scene was found in this browser. Your saved projects are in your account.')}</Empty>:<div className="import-layout"><section className="scene-shell"><p className="import-source">{t('Origen: este navegador · aún sin vincular','Source: this browser · not linked yet')}</p>{busy?<Skeleton className="skeleton-art"/>:<Art variant={1}/>}<div className="scene-caption"><strong>{t('Montaje del navegador','Browser project')}</strong><span>{t('Datos ilustrativos','Illustrative data')}</span></div></section><section className="import-note"><h2>{done?t('Un proyecto, un original intacto','One project, the original intact'):t('Decide si este montaje es tuyo','Decide whether this project is yours')}</h2><p>{t('En un equipo compartido, esta escena puede ser de otra persona. Solo se sube si eliges importarla.','On a shared device, this scene may belong to someone else. It is only uploaded if you choose to import it.')}</p><p><strong>{t('Cuenta de destino:','Destination account:')}</strong><br/>Ana Torres · ana@decoraciones.co</p>{validation&&<div className="notice error" role="alert"><div><strong>{t('Esta versión no se puede importar','This version cannot be imported')}</strong><p>{t('El archivo original sigue intacto. Descárgalo para conservarlo y pide ayuda al administrador. No abriremos una escena vacía en su lugar.','The original file is intact. Download it to keep it and ask your administrator for help. It will not be replaced with an empty scene.')}</p></div></div>}<label className="field"><span>{t('Nombre del proyecto','Project name')}</span><Input className="entry" value={name} onChange={e=>{setName(e.target.value);setInvalid(false)}} placeholder={t('Por ejemplo, Gala de octubre','For example, October gala')} disabled={done||busy||saving}/></label>{invalid&&<p className="form-error" role="alert">{t('Escribe un nombre para tu proyecto.','Enter a project name.')}</p>}<div className="actions"><B variant="default" disabled={busy||saving||offline||validation||done||!canEdit} onClick={()=>{if(!name.trim()){setInvalid(true);return}model.imported=true;projects.unshift({name:name.trim(),owner:'Ana Torres',date:'27 oct · 9:45',revision:1,style:1});model.name=name.trim();model.named=true;model.revision=1;model.notice='';m.set('state','guardado')}}>{done?t('Importado a tu cuenta','Imported to your account'):saving?t('Importando…','Importing…'):t('Importar a mi cuenta','Import to my account')}</B>{done?<B onClick={()=>go('taller')}>{t('Abrir proyecto importado','Open imported project')}</B>:<B onClick={()=>{model.importLater=true;go('lista')}}>{t('Ahora no','Not now')}</B>}<B variant="ghost" onClick={download}><Download/>{t('Descargar original de muestra','Download sample original')}</B></div><p className="preservation">{t('El original se conserva incluso después de importar. “Ahora no” permite volver desde Proyectos. En esta exploración, la importación y el archivo descargable usan datos de muestra.','The original is kept even after importing. “Not now” lets you return from Projects. In this exploration, import and download use sample data.')}</p></section></div>}
 const modalTransition=profile.reduced?{duration:0}:{...profile.spring};
 return <><style>{fonts+css}</style><div ref={root} className="estuche" data-reduced={profile.reduced}><header className="mast"><div className="brand"><span className="brand-mark" aria-hidden="true"/>Pictures <small>Sempertex</small></div><div className="mast-tools"><label className="field"><span>{t('Idioma','Language')}</span><select id="language" className="native" aria-label="Idioma / Language" value={lang} onChange={e=>{model.lang=e.target.value;setLang(e.target.value)}}><option value="es">Español</option><option value="en">English</option></select></label><label className="field actor-field"><span id="actor-label">{t('Rol de muestra','Sample role')}</span><select id="actor" aria-labelledby="actor-label" className="native" value={actor} onChange={e=>{model.actor=e.target.value;model.scope='mine';setActor(e.target.value);setScope('mine');setOwner('all');setLimit(3)}}><option value="usuario">{t('Usuario · Plan 3','User · Plan 3')}</option><option value="staff">{t('Empleado · con Taller','Staff · with Workshop')}</option><option value="lectura">{t('Empleado · solo consulta','Staff · view only')}</option></select></label></div></header><section className="page-heading"><div><h1 tabIndex={-1} className="display" style={{whiteSpace:'pre-line'}}>{forbidden?t('Sin acceso','Access denied'):ended?t('Sesión terminada','Session ended'):title}</h1><p>{m.view==='lista'?t('Cada montaje, listo para volver a tus manos.','Every project, ready to pick up again.'):t('Tu trabajo tiene un lugar. Tú decides cómo continúa.','Your work has a place. You decide what comes next.')}</p></div><div className="actions">{m.view==='lista'?<B variant="default" onClick={newProject} disabled={!canEdit||forbidden||ended||busy}><Plus/>{t('Nuevo proyecto','New project')}</B>:<B onClick={()=>go('lista')}><ArrowLeft/>{t('Proyectos','Projects')}</B>}</div></section><div className="zip-track"><motion.button className="zip-pull" role="slider" aria-label={t('Tirador decorativo: arrastra o usa las flechas','Decorative zipper: drag or use arrow keys')} aria-valuemin={-70} aria-valuemax={70} aria-valuenow={zip} title={t('Tirador de muestra · flechas para mover · Inicio para centrar','Sample zipper · arrow keys to move · Home to center')} drag={profile.reduced?false:'x'} dragConstraints={{left:-70,right:70}} dragElastic={0} dragMomentum={false} animate={{x:zip}} transition={profile.reduced?{duration:0}:profile.spring} onDragEnd={(_,info)=>setZip(Math.max(-70,Math.min(70,zip+info.offset.x)))} onKeyDown={e=>{if(['ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();setZip(v=>e.key==='Home'?0:Math.max(-70,Math.min(70,v+(e.key==='ArrowLeft'?-10:10))))}}}/></div>{forbidden||ended?<Empty title={ended?t('Vuelve a entrar con tu cuenta','Sign in with your account again'):t('Tu rol no permite abrir este proyecto','Your role cannot open this project')} action={<B onClick={retry}>{t('Volver a la sesión de muestra','Return to sample session')}</B>}>{ended?t('La vista se ha cerrado. Los borradores privados solo se recuperan al volver a la misma cuenta.','The view has been closed. Private drafts can only be recovered by returning to the same account.'):t('Pide al administrador el acceso que necesitas. No se muestra información del proyecto.','Ask your administrator for the access you need. Project information is not shown.')}</Empty>:<>{Notice()}{m.view==='lista'?List():m.view==='importar'?Import():Taller({foreign:m.view==='ajeno'})}</>}<footer className="page-foot"><p>{t('Mockup · Datos y operaciones simulados. Las miniaturas son dibujos ilustrativos; no hay guardado ni conexión a un servidor.','Mockup · Simulated data and operations. Thumbnails are illustrative drawings; no server saving or connection.')}</p><span>Estuche · C · proyectos@v1 · draft</span></footer><div className="scroll-tick" aria-hidden="true"/></div>
 <Modal.Root open={m.scene==='nombre'} onOpenChange={v=>{if(!v)close()}}><Modal.Portal><Modal.Backdrop className="overlay" transition={modalTransition}/><Modal.Popup className="dialog-box" transition={modalTransition}><Modal.Title render={<h2/>}>{model.copy?t('Una copia para continuar','A copy to continue'):t('Guarda tu proyecto con nombre','Give your project a name')}</Modal.Title><Modal.Description className="description">{model.copy?t('Se creará un proyecto en tu cuenta. El original no cambia.','A project will be created in your account. The original stays unchanged.'):t('Este primer guardado es tuyo. Después, los cambios se guardarán automáticamente.','This first save is yours. Later changes will save automatically.')}</Modal.Description><B className="dialog-close" variant="ghost" aria-label={t('Cerrar','Close')} onClick={close}><X/></B><form onSubmit={e=>{e.preventDefault();commitName()}}><label className="field"><span>{t('Nombre del proyecto','Project name')}</span><Input autoFocus className="entry" value={name} aria-invalid={invalid||validation} aria-describedby={invalid||validation?'name-error':undefined} onChange={e=>{setName(e.target.value);setInvalid(false)}}/></label>{(invalid||validation)&&<p id="name-error" className="form-error" role="alert">{t('Escribe un nombre que permita reconocer tu montaje.','Enter a name that helps identify your project.')}</p>}<div className="actions"><B variant="default" type="submit" disabled={saving||offline||busy||!canEdit}>{t(model.copy?'Guardar copia':'Guardar proyecto',model.copy?'Save copy':'Save project')}</B><B type="button" onClick={close}>{t('Cancelar','Cancel')}</B></div></form></Modal.Popup></Modal.Portal></Modal.Root>
 <Confirm.Root open={m.scene==='salir'||m.scene==='servidor'} onOpenChange={v=>{if(!v)close()}}><Confirm.Portal><Confirm.Backdrop className="overlay" transition={modalTransition}/><Confirm.Popup className="dialog-box" transition={modalTransition}><Confirm.Title render={<h2/>}>{m.scene==='servidor'?t('¿Cargar la versión guardada?','Load the saved version?'):t('Hay trabajo pendiente de guardar','There is unsaved work')}</Confirm.Title><Confirm.Description className="description">{m.scene==='servidor'?t('La versión guardada sustituirá lo que ves en el Taller. Conservaremos tu trabajo actual como borrador local de esta cuenta.','The saved version will replace what you see in the Workshop. Your current work will be kept as a local draft for this account.'):t('Antes de cambiar de proyecto, elige cómo conservar tu montaje. El borrador local solo estará disponible en este navegador y con esta cuenta.','Before switching projects, choose how to keep your work. The local draft is only available in this browser and with this account.')}</Confirm.Description><div className="actions">{m.scene==='servidor'?<B variant="default" onClick={()=>{model.localKept=true;model.dirty=false;model.auto=false;model.revision++;model.notice=t('Borrador local conservado. Se cargó la versión de la cuenta.','Local draft kept. Account version loaded.');close();m.set('state','guardado')}}>{t('Conservar borrador y cargar','Keep draft and load')}</B>:<><B variant="default" disabled={offline||conflict||saving||!canEdit} onClick={()=>{close();save()}}>{t('Guardar antes de salir','Save before leaving')}</B><B onClick={()=>{model.localKept=true;model.dirty=false;model.auto=false;close();m.set('state','normal');m.set('view','lista')}}>{t('Conservar borrador y salir','Keep draft and leave')}</B></>}<B onClick={close}>{t('Seguir aquí','Stay here')}</B></div></Confirm.Popup></Confirm.Portal></Confirm.Root>
 </>;
}
mountMockup(App,{title:'Proyectos · Estuche C',motion:'expressive',views:[{id:'lista',label:'Proyectos'},{id:'taller',label:'Guardado en Taller'},{id:'ajeno',label:'Proyecto ajeno · lectura'},{id:'importar',label:'Importar del navegador'}],states:[{id:'normal',label:'Normal'},{id:'cargando',label:'Cargando'},{id:'vacio',label:'Vacío'},{id:'error',label:'Error recuperable'},{id:'pendiente',label:'Cambios pendientes'},{id:'guardando',label:'Guardando / importando'},{id:'guardado',label:'Guardado / importado'},{id:'sinconexion',label:'Sin conexión'},{id:'conflicto',label:'Conflicto de versiones'},{id:'validacion',label:'Validación'},{id:'sinpermiso',label:'Sin permiso'},{id:'sesion',label:'Sesión terminada'},{id:'paginaerror',label:'Error siguiente página'}],scenes:[{id:'',label:'Ninguno'},{id:'nombre',label:'Nombre / guardar copia'},{id:'salir',label:'Salir con cambios'},{id:'servidor',label:'Cargar versión guardada'}]});
